const makeQuestion = ({
  id,
  topicId,
  tags,
  question,
  questionHindi,
  options,
  optionsHindi,
  correctAnswer,
  hints,
  hintsHindi,
  explanation,
  explanationHindi,
  difficulty = "medium",
  eloRating = 1325,
  interval = 10,
  marks = 1,
  negativeMarks = 0,
}) => ({
  id,
  subjectId: "9-maths",
  class: 9,
  topicId,
  tags,
  question,
  questionHindi,
  options,
  optionsHindi,
  correctAnswer,
  hints,
  hintsHindi,
  type: "mcq",
  explanation,
  explanationHindi,
  difficulty,
  eloRating: Math.max(1200, Math.min(1450, eloRating)),
  interval,
  marks,
  negativeMarks,
});

const makeQuestionSet = (topicId, rows) =>
  rows.map(
    ([
      id,
      tags,
      question,
      questionHindi,
      options,
      optionsHindi,
      correctAnswer,
      hints,
      hintsHindi,
      explanation,
      explanationHindi,
      difficulty,
      eloRating,
    ]) =>
      makeQuestion({
        id,
        topicId,
        tags,
        question,
        questionHindi,
        options,
        optionsHindi,
        correctAnswer,
        hints,
        hintsHindi,
        explanation,
        explanationHindi,
        difficulty,
        eloRating,
      })
  );

const makeAutoQuestionSet = (topicId, prefix, specs) =>
  specs.map((spec, index) => {
    const correctAnswer = index % 4;
    const options = [...spec.distractors];
    const optionsHindi = [...spec.distractorsHindi];
    options.splice(correctAnswer, 0, spec.answer);
    optionsHindi.splice(correctAnswer, 0, spec.answerHindi);
    return makeQuestion({
      id: `${prefix}-${String(index + 1).padStart(2, "0")}`,
      topicId,
      tags: spec.tags,
      question: spec.question,
      questionHindi: spec.questionHindi,
      options: options.slice(0, 4),
      optionsHindi: optionsHindi.slice(0, 4),
      correctAnswer,
      hints: [spec.hint],
      hintsHindi: [spec.hintHindi],
      explanation: spec.explanation,
      explanationHindi: spec.explanationHindi,
      difficulty: spec.difficulty || "medium",
      eloRating: spec.eloRating || 1325,
    });
  });

const spec = ({
  tags,
  question,
  questionHindi,
  answer,
  answerHindi = answer,
  distractors,
  distractorsHindi = distractors,
  hint,
  hintHindi,
  explanation,
  explanationHindi,
  difficulty = "medium",
  eloRating = 1325,
}) => ({
  tags,
  question,
  questionHindi,
  answer: String(answer),
  answerHindi: String(answerHindi),
  distractors: distractors.map(String),
  distractorsHindi: distractorsHindi.map(String),
  hint,
  hintHindi,
  explanation,
  explanationHindi,
  difficulty,
  eloRating,
});

const degree = (value) => `${value}°`;
const cm = (value) => `${value} cm`;
const cmHi = (value) => `${value} सेमी`;
const sqcm = (value) => `${value} cm²`;
const sqcmHi = (value) => `${value} सेमी²`;
const cubecm = (value) => `${value} cm³`;
const cubecmHi = (value) => `${value} सेमी³`;

