      hint: "Arc length = (θ/360) × 2πr.",
      hintHindi: "चाप लंबाई = (θ/360) × 2πr।",
      explanation: `Arc length = (${theta}/360) × 2 × 22/7 × ${r} = ${cm(ans)}.`,
