        "भारतीय गणित ने विश्व को अद्वितीय और दूरगामी योगदान दिए हैं। इस अध्याय में जिस पर सबसे अधिक बल दिया गया है, उसके अनुसार निम्नलिखित में से किसे वैश्विक गणित के लिए भारत का सबसे प्रभावशाली उपहार माना जाता है?",
