        ["Ancient Vedic verses were composed in an era before the printing press or widespread paper use, and were famous for being preserved through recitation."],
        ["प्राचीन वैदिक श्लोक छापेखाने या व्यापक कागज़ उपयोग के युग से पहले रचे गए थे, और पाठ के माध्यम से संरक्षित होने के लिए प्रसिद्ध थे।"],
        "Vedic verses, including those from Vedanga Jyotisha, were preserved and transmitted for centuries mainly through oral tradition — careful memorization and recitation passed from teacher to student.",
