        1,
        ["The chapter opens by saying that signs of basic mathematical knowledge exist even before what we consider the oldest written documents."],
        ["अध्याय की शुरुआत में कहा गया है कि जिन्हें हम सबसे पुराना लिखित दस्तावेज़ मानते हैं, उनसे भी पहले बुनियादी गणितीय ज्ञान के संकेत मौजूद हैं।"],
        "The scraped geometric patterns on ochre rocks support the chapter's opening claim that hints of basic mathematical/geometric knowledge existed even before humanity's oldest known written documents.",
        "गेरू चट्टानों पर खुरचे गए ज्यामितीय पैटर्न अध्याय के आरंभिक दावे का समर्थन करते हैं कि मानवता के सबसे पुराने ज्ञात लिखित दस्तावेज़ों से भी पहले बुनियादी गणितीय/ज्यामितीय ज्ञान के संकेत विद्यमान थे।",
