        2,
        ["The chapter specifically names four ancient regions/peoples alongside India that made important contributions."],
        ["अध्याय भारत के साथ-साथ चार विशिष्ट प्राचीन क्षेत्रों/समुदायों का नाम लेता है जिन्होंने महत्वपूर्ण योगदान दिया।"],
