        "श्लोक का संस्कृत शब्द 'खगुण' सीधे शून्य से गुणा (a × 0 = 0) को दर्शाता है, जो उसी श्लोक में शामिल योग, वर्ग और भाग के साथ बुनियादी नियमों के समुच्चय को पूर्ण करता है।",
        "hard", 1410
