        "In modern algebra, zero is called the 'additive identity' because adding it to any number a leaves that number unchanged: a + 0 = a. This is exactly the rule Brahmagupta stated over a thousand years ago.",
        "आधुनिक बीजगणित में, शून्य को 'योज्य तत्समक' (additive identity) कहा जाता है क्योंकि इसे किसी भी संख्या a में जोड़ने पर वह संख्या अपरिवर्तित रहती है: a + 0 = a। यह ठीक वही नियम है जो ब्रह्मगुप्त ने एक हज़ार वर्ष से भी पहले बताया था।",
