        "Trigonometric ratios depend only on the ANGLE θ, not on the size of the triangle. This is because similar triangles (same angles) have proportional sides, so ratios like opposite/hypotenuse remain constant regardless of scale.",
        "त्रिकोणमितीय अनुपात केवल कोण θ पर निर्भर करते हैं, त्रिभुज के आकार पर नहीं। ऐसा इसलिए है क्योंकि समरूप त्रिभुजों (समान कोण) की भुजाएं आनुपातिक होती हैं, इसलिए सम्मुख/कर्ण जैसे अनुपात, आकार की परवाह किए बिना स्थिर रहते हैं।",
